const fs = require('fs')
const path = require('path')
for (const l of fs.readFileSync('/root/app/.env', 'utf8').split('\n')) {
  const m = l.match(/^([A-Z_]+)=(.*)$/)
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^"|"$/g, '')
}
const { PrismaClient } = require(path.join('/root/app/node_modules/@prisma/client'))
const db = new PrismaClient()
async function main() {
  const users = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'))
  for (const u of users) {
    const data = {
      name: u.name,
      stripeCustomerId: u.stripeCustomerId,
      stripeSubscriptionId: u.stripeSubscriptionId,
      stripePriceId: u.stripePriceId,
      stripeCurrentPeriodEnd: u.stripeCurrentPeriodEnd ? new Date(u.stripeCurrentPeriodEnd * 1000) : null,
    }
    await db.user.upsert({ where: { email: u.email }, update: data, create: { email: u.email, ...data } })
    console.log('seeded', u.email)
  }
}
main().finally(() => db.$disconnect())

